mapper.select:
SELECT * FROM( SELECT order_term_conditions.term_condition_type_id AS typeId, term_condition_types.name AS typeName, order_term_conditions.term_condition_id AS id, term_conditions.name AS name FROM order_term_conditions INNER JOIN term_condition_types ON term_condition_types.id = order_term_conditions.term_condition_type_id INNER JOIN term_conditions ON term_conditions.id = order_term_conditions.term_condition_id WHERE order_id = #{saleOrderId}
UNION ALL
SELECT term_condition_applies.term_condition_type_id AS typeId, term_condition_types.name AS typeName, IFNULL(term_condition_applies.term_condition_default_id, 0) AS id, IFNULL(term_conditions.name, '') AS name FROM term_condition_applies INNER JOIN term_condition_types ON term_condition_types.id = term_condition_applies.term_condition_type_id LEFT JOIN term_conditions ON term_conditions.id = term_condition_applies.term_condition_default_id WHERE term_condition_applies.is_active = 1 AND term_condition_applies.module_type_id IN (SELECT id FROM module_types WHERE status = 1 AND (name = 'Sales Order' OR name = 'Sales Order (Software)')) AND EXISTS ( SELECT 1 FROM order_term_conditions WHERE order_term_conditions.order_id = #{saleOrderId} AND order_term_conditions.term_condition_type_id = term_condition_applies.term_condition_type_id ) ) as results GROUP BY typeId

