UPDATE orders SET


        is_approve = 1,


        is_approve = 0,


approved = NOW(),
approved_by = #{userId}
WHERE id = #{id} AND status > 0;

UPDATE orders SET
is_close = #{status},
approved = NOW(),
approved_by = #{userId}
WHERE id = #{id}

mapper.select:
SELECT COUNT(*) AS total
FROM (
         SELECT id FROM order_details WHERE order_id = #{saleOrderId}
         UNION ALL
         SELECT id FROM order_services WHERE order_id = #{saleOrderId}
         UNION ALL
         SELECT id FROM order_miscs WHERE order_id = #{saleOrderId}
     ) AS combined
